# -*- coding: utf-8 -*-
"""Build a dependency-free, offline annotation viewer from the checked-in data."""
import csv
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
rows = [json.loads(line) for line in (ROOT / 'outputs/errors.jsonl').read_text().splitlines()]
pilot = [r['error_id'] for r in csv.DictReader((ROOT / 'annotation/human_pilot_A.csv').open())]
dev = json.loads((ROOT / 'annotation/dev50_candidate_manifest.json').read_text())
zh = json.loads((ROOT / 'annotation/pilot_zh.json').read_text())['translations']
payload = json.dumps({'dev': dev, 'zh': zh, 'errors': rows, 'pilot': pilot, 'rubric': (ROOT / 'annotation/rubric.md').read_text(), 'version': hashlib.sha256((ROOT / 'outputs/errors.jsonl').read_bytes()).hexdigest()[:12]}, ensure_ascii=False).replace('<', '\\u003c')
html = r'''<!doctype html>
<html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ASR 语义错误 · 人工标注</title>
<style>
:root{--ink:#18293f;--muted:#61748b;--line:#d9e2ec;--blue:#265bd5;--paper:#fff;--bg:#eef3f9;--ref:#a32c68;--hyp:#086f72}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.6 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}button,input,select,textarea{font:inherit}button,select{cursor:pointer}button{background:white;border:1px solid var(--line);border-radius:7px;padding:7px 12px;color:var(--ink)}button:hover{border-color:var(--blue)}:focus-visible{outline:3px solid #83abff;outline-offset:2px}header{background:#fff;padding:20px 30px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:20px}h1{font-size:23px;letter-spacing:-.6px;margin:0;font-weight:700}header p{margin:3px 0 0;color:var(--muted);font-size:13px}.actions{display:flex;gap:8px;flex-wrap:wrap}.primary{background:var(--blue);border-color:var(--blue);color:#fff}.notice{margin:16px 24px 0;padding:10px 15px;background:#e3ecff;border-left:3px solid var(--blue);font-size:13px}.layout{display:grid;grid-template-columns:240px minmax(350px,1fr) 320px;gap:18px;padding:18px 24px;max-width:1800px;margin:auto}.panel{background:var(--paper);border:1px solid var(--line);border-radius:10px;padding:20px}aside.panel{padding:15px;height:calc(100vh - 190px);position:sticky;top:18px;display:flex;flex-direction:column}.muted{color:var(--muted);font-size:13px}.label{font-size:12px;font-weight:650;letter-spacing:.5px;color:var(--muted);margin:0 0 9px}select,input[type=search],textarea{width:100%;border:1px solid var(--line);border-radius:6px;background:#fff;padding:8px;color:var(--ink)}select{margin-bottom:10px}input[type=search]{margin-bottom:10px}.list{overflow:auto;flex:1;margin-top:10px}.item{display:block;text-align:left;width:100%;border:0;border-bottom:1px solid #edf0f5;border-radius:0;padding:11px 8px}.item.active{background:#edf3ff;border-left:3px solid var(--blue)}.item small{display:block;color:var(--muted)}.item .preview{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:180px;font-family:Georgia,serif}.track{height:5px;background:#e7edf5;border-radius:10px;margin:8px 0}.track div{height:100%;background:var(--blue);border-radius:10px}.topline{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:17px}.context p{margin:0;padding:6px 10px;color:#57697e;font:16px/1.6 Georgia,"Times New Roman",serif}.zh{font:14px/1.8 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;color:#405e7f;margin:6px 0 0;padding:7px 10px;border-left:2px solid #b9cdec;background:#f5f8fc}.zh-label{font-size:11px;color:#7085a0;margin-right:6px}.zh-pending{color:#78879a}body.hide-zh .zh{display:none}.context .zh{display:block;margin:5px 0 0;padding:0;background:transparent;border:0;font:14px/1.8 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;color:#405e7f}.context .target{background:#f1f5fb;border-left:3px solid #9eb4d1;color:var(--ink)}.context .speaker{font:11px/1.6 ui-monospace,monospace;display:block;color:var(--muted)}.diff{margin:22px 0;display:grid;grid-template-columns:1fr 34px 1fr;align-items:stretch}.chunk{padding:15px 16px;background:#fdf0f6;border-top:3px solid var(--ref);overflow-wrap:anywhere}.chunk.hyp{background:#eaf6f4;border-color:var(--hyp)}.chunk .label{color:var(--ref)}.chunk.hyp .label{color:var(--hyp)}.words{font:26px/1.35 Georgia,"Times New Roman",serif}.arrow{align-self:center;text-align:center;color:var(--muted)}.sentence{font:20px/1.7 Georgia,"Times New Roman",serif;overflow-wrap:anywhere}mark{background:#e3ecff;color:#174db8;border-radius:3px;padding:2px 4px}.block{padding:18px 0;border-top:1px solid var(--line)}.block p{margin:0}.foot{font:11px/1.6 ui-monospace,monospace;color:var(--muted);overflow-wrap:anywhere}h2{font-size:17px;margin:0 0 5px}.question{margin:0 0 16px;color:var(--muted);font-size:13px}.scores{display:flex;flex-direction:column;gap:7px;margin-bottom:18px}.score{display:flex;align-items:center;text-align:left;gap:13px;padding:10px}.score b{font:24px/1 Georgia,serif;width:24px;color:var(--blue)}.score span{font-size:13px}.score.selected{background:#edf3ff;border-color:var(--blue);box-shadow:inset 0 0 0 1px var(--blue)}label.field{display:block;font-size:12px;color:var(--muted);margin:12px 0 5px}textarea{resize:vertical;min-height:80px}.nav{display:flex;gap:8px;margin-top:16px}.nav button{flex:1}#save{min-height:24px;font-size:12px;color:#08716d;margin-top:10px}.empty{padding:40px 10px;color:var(--muted)}dialog{border:1px solid var(--line);border-radius:12px;max-width:850px;width:90%;padding:26px}dialog::backdrop{background:#18293f88}#rubricText{white-space:pre-wrap;font:14px/1.9 -apple-system,"PingFang SC",sans-serif}details{font-size:12px;color:var(--muted);margin-top:10px}progress{width:100%}@media(min-width:1200px){main.panel{padding:26px 30px}}@media(max-width:1100px){.layout{grid-template-columns:200px minmax(300px,1fr)}.rating{grid-column:2}}@media(max-width:700px){header{padding:16px;align-items:flex-start;flex-direction:column}.notice{margin:12px}.layout{padding:12px;display:flex;flex-direction:column}.panel{padding:17px}aside.panel{position:static;height:auto}.list{max-height:160px}.item .preview{max-width:90%}.diff .words{font-size:22px}}

.mobile-toolbar{display:none}button,select{touch-action:manipulation}input,select,textarea{font-size:16px}
@media(max-width:700px){header{gap:12px}h1{font-size:20px}.actions{gap:7px;width:100%}.actions button{font-size:13px;min-height:42px;flex:1 0 auto}.notice{font-size:12px}.mobile-toolbar{display:flex;align-items:center;justify-content:space-between;margin:12px;gap:10px}.mobile-toolbar button{min-height:44px}.mobile-toolbar span{font-size:13px;color:var(--muted)}aside.panel{display:none}body.filters-open aside.panel{display:flex}.layout{padding-top:0;gap:12px}#sample{min-width:0}.context p{font-size:17px}.context .zh{font-size:14px}.sentence{font-size:19px}.score{min-height:56px}.rating{padding-bottom:max(22px,env(safe-area-inset-bottom))}.rating .nav{position:sticky;bottom:0;background:white;padding:10px 0;z-index:2}.nav button{min-height:48px}.diff{grid-template-columns:minmax(0,1fr) 26px minmax(0,1fr)}.chunk{padding:12px}.topline h2{font-size:16px}.list{max-height:220px}}
</style>
<header><div><h1>听懂了吗？ <span style="font-weight:400;color:var(--muted)">/ ASR 语义标注</span></h1><p>只判断标出的一个错误：它让读者误解或丢失了多少信息？</p></div><div class="actions"><button id="toggleZh" aria-pressed="true">中文辅助：开</button><button id="rubricOpen">完整评分规则</button><button id="idsExport">下载当前 ID 名单</button><button id="backup">备份 JSON</button><button id="import">恢复备份</button><button class="primary" id="export">导出 CSV</button><input id="file" type="file" accept=".json,application/json" hidden></div></header>
<div class="notice">默认显示 dev 候选 50 条（待你和 Demi 确认）：从旧 80 条按系统与对齐错误类型抽取，每个 ASR 系统 25 条。仓库尚无正式 50 条名单；若 Demi 已有名单，请以她的为准。旧 80 条与已有评分均保留，可切换查看。中文仅供辅助。</div>
<div class="mobile-toolbar"><button id="toggleFilters" aria-expanded="false">展开筛选</button><span id="mobileProgress"></span></div><div class="layout"><aside class="panel" id="filtersPanel"><label class="label" for="dataset">样本范围</label><select id="dataset"><option value="dev">Dev 候选 · 50 条（待确认）</option><option value="pilot">旧版 pilot · 80 条</option><option value="all">全部错误 · 1,287 条</option></select><select id="status" aria-label="标注状态"><option value="all">所有状态</option><option value="todo">未完成</option><option value="done">已完成</option></select><input id="search" type="search" placeholder="搜索文本或 ID" aria-label="搜索样本"><div id="count" class="muted"></div><div class="track"><div id="bar"></div></div><div class="muted">完成 = 严重度 + 内容 + 错误形式</div><div id="list" class="list"></div></aside>
<main class="panel" id="sample"></main><section class="panel rating"><h2>这个错误，影响多大？</h2><p class="question">其余错误当作不存在。先独立判断，再讨论。</p><div class="scores" id="scores"></div><label class="field" for="content_type">受影响的内容 · content_type</label><select id="content_type"></select><label class="field" for="error_form">错误形式 · error_form</label><select id="error_form"></select><label class="field" for="flag">特殊情况 · flag（可空）</label><select id="flag"></select><label class="field" for="note">备注 · note（可空）</label><textarea id="note" placeholder="不确定的原因、上下文线索……"></textarea><div id="save" role="status" aria-live="polite"></div><div class="nav"><button id="prev">← 上一条</button><button id="next" class="primary">下一条 →</button></div><button id="nextTodo" style="width:100%;margin-top:8px">跳到下一条未完成</button><details><summary>保存说明与快捷键</summary>更改自动保存在当前浏览器。请定期备份 JSON 或导出 CSV；清除浏览器数据可能丢失标注。无输入框焦点时按 1–5 评分、← → 翻页。CSV 导出当前样本范围内的全部条目，包含未完成条目。</details></section></div>
<dialog id="rubric"><div class="topline"><h2>标注规则 v1</h2><button id="rubricClose">关闭</button></div><p class="notice" style="margin:0 0 15px">下方原始规则仍写 80 条 pilot；项目计划为 50 dev + 200 test。本页默认 50 条为候选名单，须双方确认后共同使用。</p><div id="rubricText"></div></dialog>
<script id="data" type="application/json">__PAYLOAD__</script>
<script>
'use strict';
const DATA=JSON.parse(document.getElementById('data').textContent), $=id=>document.getElementById(id), key='semwer-human-v1-'+DATA.version;
const fields=['severity','content_type','error_form','flag','note'];
const choices={content_type:[['disfluency','语气词 / 重复 / 口吃'],['function_word','虚词'],['content_word','实词'],['named_entity','命名实体'],['number','数字 / 价格 / 时间'],['negation','命题否定'],['other','其他']],error_form:[['deletion','删除'],['insertion','插入'],['morph_variant','形态变化'],['nonword','非词'],['real_word','真词替换'],['garbled','乱码']],flag:[['ref_issue','参考文本有问题'],['crosstalk','串音']]};
let answers={},storageOK=true;try{answers=JSON.parse(localStorage.getItem(key)||'{}')}catch(e){storageOK=false}
let current=DATA.dev.ids[0],visible=[],viewSignature='';const byId=new Map(DATA.errors.map(e=>[e.error_id,e]));
let showZh=true;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const zhHtml=(text,inline=false)=>{const zh=DATA.zh[text];if(!zh)return `<${inline?'span':'div'} class="zh zh-pending">此句不在 80 条 pilot 译文范围内</${inline?'span':'div'}>`;return `<${inline?'span':'div'} class="zh"><span class="zh-label">中文辅助</span>${esc(zh)}</${inline?'span':'div'}>`};
const done=id=>{const a=answers[id]||{};return [1,2,3,4,5].includes(+a.severity)&&choices.content_type.some(x=>x[0]===a.content_type)&&choices.error_form.some(x=>x[0]===a.error_form)};
const scope=()=>($('dataset').value==='dev'?DATA.dev.ids:$('dataset').value==='pilot'?DATA.pilot:DATA.errors.map(e=>e.error_id));
function persist(){try{localStorage.setItem(key,JSON.stringify(answers));storageOK=true;$('save').textContent='已保存到此浏览器 · 请定期导出'}catch(e){storageOK=false;$('save').textContent='浏览器无法保存，请立即导出备份'}}
function renderList(){const ids=scope(),q=$('search').value.trim().toLowerCase(),status=$('status').value;visible=ids.filter(id=>{const e=byId.get(id);return (status==='all'||(status==='done'?done(id):!done(id)))&&(!q||[e.ref,e.hyp,e.error_id,e.ref_span,e.hyp_span].join(' ').toLowerCase().includes(q))});const n=ids.filter(done).length;$('mobileProgress').textContent=`已完成 ${n} / ${ids.length}`;$('count').textContent=`已完成 ${n} / ${ids.length} · 筛选 ${visible.length} 条`;$('bar').style.width=(100*n/ids.length)+'%';if(!visible.includes(current))current=visible[0]||null;$('list').innerHTML=visible.map((id,i)=>{const e=byId.get(id);return `<button class="item ${id===current?'active':''}" data-id="${esc(id)}"><small>${done(id)?'✓':'○'} ${i+1} · ${esc(e.meeting_id)}${$('dataset').value==='dev'?' · 旧#'+(DATA.pilot.indexOf(id)+1):''}</small><span class="preview">${esc(e.ref_span||'∅')} → ${esc(e.hyp_span||'∅')}</span></button>`}).join('')||'<p class="empty">没有符合条件的样本，试试切换范围或状态。</p>';$('list').querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>{current=b.dataset.id;render()})}
function renderSample(){const e=byId.get(current);document.querySelectorAll('.rating button,.rating select,.rating textarea').forEach(x=>x.disabled=!e);if(!e){$('sample').innerHTML='<div class="empty">当前没有样本。</div>';return}const marked=esc(e.ref_marked).replace(/\[\[([\s\S]*?)\]\]/g,'<mark>$1</mark>');const ctx=(s,target=false)=>{const m=s.match(/^([^:]+):\s*([\s\S]*)$/);return `<p class="${target?'target':''}">${m?`<span class="speaker">${esc(m[1])}</span>${esc(m[2])}`:esc(s)}${zhHtml(s,true)}</p>`};$('sample').innerHTML=`<div class="topline"><h2>会议上下文</h2><span class="muted">${visible.indexOf(current)+1} / ${visible.length} · ${esc(e.meeting_id)}</span></div><div class="context">${e.context_before.map(s=>ctx(s)).join('')}<p class="target"><span class="speaker">目标句 · 人工参考文本</span>${esc(e.ref)}${zhHtml(e.ref,true)}</p>${e.context_after.map(s=>ctx(s)).join('')}</div><div class="diff"><div class="chunk"><p class="label">原文 · 人实际说的</p><div class="words">${esc(e.ref_span||'∅')}</div></div><span class="arrow">→</span><div class="chunk hyp"><p class="label">ASR · 识别成了</p><div class="words">${esc(e.hyp_span||'∅')}</div></div></div><div class="block"><p class="label">原文整句 · 仅评价高亮片段</p><div class="sentence">${marked}</div>${zhHtml(e.ref)}</div><div class="block"><p class="label">ASR 整句</p><div class="sentence">${esc(e.hyp||'∅')}</div>${zhHtml(e.hyp)}</div><p class="muted">∅ 表示这一侧为空。删掉重复词可能无影响，删掉否定词可能改变结论。</p><details><summary>样本来源</summary><p class="foot">${esc(e.error_id)}</p></details>`;const a=answers[current]||{};document.querySelectorAll('[data-score]').forEach(b=>{b.classList.toggle('selected',+b.dataset.score===+a.severity);b.setAttribute('aria-pressed',String(+b.dataset.score===+a.severity))});['content_type','error_form','flag','note'].forEach(f=>$(f).value=a[f]||'');$('save').textContent=storageOK?'更改自动保存在此浏览器':'浏览器保存不可用，请导出备份'}
function render(){renderList();renderSample()}
function update(f,v){if(!current)return;const id=current;answers[id]={...(answers[id]||{}),[f]:v};persist();if(f!=='note'){renderList();renderSample()} }
const levels=[['无影响','意思完全不变'],['轻微','可以确定地还原原意'],['中等','局部模糊，可能猜错'],['严重','关键信息丢失或被误导'],['关键','事实 / 结论改变，无法纠正']];$('scores').innerHTML=levels.map((x,i)=>`<button class="score" data-score="${i+1}" aria-pressed="false"><b>${i+1}</b><span><strong>${x[0]}</strong> · ${x[1]}</span></button>`).join('');document.querySelectorAll('[data-score]').forEach(b=>b.onclick=()=>update('severity',+b.dataset.score));
for(const [f,opts]of Object.entries(choices)){$(f).innerHTML=`<option value="">${f==='flag'?'无特殊情况':'请选择'}</option>`+opts.map(([v,l])=>`<option value="${v}">${l} · ${v}</option>`).join('');$(f).onchange=()=>update(f,$(f).value)}$('note').oninput=()=>update('note',$('note').value);
['dataset','status'].forEach(id=>$(id).onchange=render);$('search').oninput=render;
function step(d){const i=visible.indexOf(current);if(i+d>=0&&i+d<visible.length){current=visible[i+d];render()}}$('prev').onclick=()=>step(-1);$('next').onclick=()=>step(1);$('nextTodo').onclick=()=>{const i=visible.indexOf(current),ordered=[...visible.slice(i+1),...visible.slice(0,i+1)],id=ordered.find(x=>!done(x));if(id){current=id;render()}else $('save').textContent='当前筛选结果已全部完成'};
document.addEventListener('keydown',e=>{if($('rubric').open||/INPUT|TEXTAREA|SELECT|BUTTON/.test(document.activeElement.tagName)||e.metaKey||e.ctrlKey||e.altKey)return;if(/^[1-5]$/.test(e.key))update('severity',+e.key);if(e.key==='ArrowRight')step(1);if(e.key==='ArrowLeft')step(-1)});
$('toggleFilters').onclick=()=>{const open=document.body.classList.toggle('filters-open');$('toggleFilters').textContent=open?'收起筛选':'展开筛选';$('toggleFilters').setAttribute('aria-expanded',String(open))};
$('toggleZh').onclick=()=>{showZh=!showZh;document.body.classList.toggle('hide-zh',!showZh);$('toggleZh').textContent='中文辅助：'+(showZh?'开':'关');$('toggleZh').setAttribute('aria-pressed',String(showZh))};
$('rubricText').textContent=DATA.rubric;$('rubricOpen').onclick=()=>$('rubric').showModal();$('rubricClose').onclick=()=>$('rubric').close();
function download(name,text,mime){const u=URL.createObjectURL(new Blob([text],{type:mime})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
$('idsExport').onclick=()=>download('semwer_'+$('dataset').value+'_ids.txt',scope().join('\n')+'\n','text/plain;charset=utf-8');
$('backup').onclick=()=>download('semwer_annotations_backup.json',JSON.stringify({datasetVersion:DATA.version,answers},null,2),'application/json');
$('export').onclick=()=>{const cols=['error_id','context','原文_said','ASR_output','原文整句_[[原文→ASR]]','ASR整句',...fields],quote=x=>'"'+String(x??'').replace(/"/g,'""')+'"';const rows=scope().map(id=>{const e=byId.get(id),a=answers[id]||{};return [id,[...e.context_before,'[TARGET] '+e.ref,...e.context_after].join('\n'),e.ref_span||'∅',e.hyp_span||'∅',e.ref_marked,e.hyp,...fields.map(f=>a[f]??'')]});download('human_'+($('dataset').value==='dev'?'dev50_candidate':$('dataset').value)+'_annotations.csv','\ufeff'+[cols,...rows].map(r=>r.map(quote).join(',')).join('\r\n'),'text/csv;charset=utf-8')};
$('import').onclick=()=>$('file').click();$('file').onchange=async()=>{const file=$('file').files[0];if(!file)return;try{const obj=JSON.parse(await file.text());if(obj.datasetVersion!==DATA.version||!obj.answers||typeof obj.answers!=='object'||Array.isArray(obj.answers))throw Error('备份的数据版本与本页不一致');const valid={};for(const [id,a]of Object.entries(obj.answers)){if(!byId.has(id)||!a||typeof a!=='object'||Array.isArray(a))throw Error('备份包含无效条目');if(a.severity!==undefined&&a.severity!==''&&![1,2,3,4,5].includes(+a.severity))throw Error('备份包含无效评分');for(const f of Object.keys(choices)){if(a[f]&&!choices[f].some(x=>x[0]===a[f]))throw Error('备份包含无效类别')}valid[id]=Object.fromEntries(fields.filter(f=>a[f]!==undefined).map(f=>[f,a[f]]))}const conflicts=Object.keys(valid).filter(id=>answers[id]&&JSON.stringify(answers[id])!==JSON.stringify(valid[id]));if(conflicts.length&&!confirm(`备份与当前 ${conflicts.length} 条记录不同，是否用备份覆盖这些记录？`))return;answers={...answers,...valid};persist();render();$('save').textContent=`已恢复 ${Object.keys(valid).length} 条记录`}catch(e){alert('无法恢复：'+e.message)}finally{$('file').value=''}};
render();
</script></html>'''
out = ROOT / 'annotation/viewer.html'
out.write_text(html.replace('__PAYLOAD__', payload))
print(f'{out}: {len(rows)} errors, {len(pilot)} pilot items, {out.stat().st_size:,} bytes')
